using System;
using System.Collections.Generic;
public static class TfMathChecks {
 public static int Checks; public static double WorstError;
 static double[,] I(){return new double[,]{{1,0,0},{0,1,0},{0,0,1}};}
 static double[,] Mul(double[,] a,double[,] b){var c=new double[3,3];for(int i=0;i<3;i++)for(int j=0;j<3;j++)for(int k=0;k<3;k++)c[i,j]+=a[i,k]*b[k,j];return c;}
 static double[] Apply(double[,] a,double[] b){var c=new double[3];for(int i=0;i<3;i++)for(int j=0;j<3;j++)c[i]+=a[i,j]*b[j];return c;}
 static double[,] Trans(double[,] a){var b=new double[3,3];for(int i=0;i<3;i++)for(int j=0;j<3;j++)b[i,j]=a[j,i];return b;}
 static double[] Add(double[] a,double[] b){return new[]{a[0]+b[0],a[1]+b[1],a[2]+b[2]};}
 static double[] Neg(double[] a){var b=new double[a.Length];for(int i=0;i<a.Length;i++)b[i]=-a[i];return b;}
 static void Near(double[] a,double[] b,string name,double tol=1e-9){if(a.Length!=b.Length)throw new Exception(name+" dimension");double err=0;for(int i=0;i<a.Length;i++)err=Math.Max(err,Math.Abs(a[i]-b[i]));if(double.IsNaN(err)||err>tol)throw new Exception(name+" error "+err);Checks++;WorstError=Math.Max(WorstError,err);}
 static void Near(double[,] a,double[,] b,string name){var av=new double[9];var bv=new double[9];for(int i=0;i<3;i++)for(int j=0;j<3;j++){av[3*i+j]=a[i,j];bv[3*i+j]=b[i,j];}Near(av,bv,name);}
 static double Det(double[,] a){return a[0,0]*(a[1,1]*a[2,2]-a[1,2]*a[2,1])-a[0,1]*(a[1,0]*a[2,2]-a[1,2]*a[2,0])+a[0,2]*(a[1,0]*a[2,1]-a[1,1]*a[2,0]);}
 static double[,] Axis(int axis,double v){double c=Math.Cos(v),s=Math.Sin(v);if(axis==0)return new double[,]{{1,0,0},{0,c,-s},{0,s,c}};if(axis==1)return new double[,]{{c,0,s},{0,1,0},{-s,0,c}};return new double[,]{{c,-s,0},{s,c,0},{0,0,1}};}
 static double[,] Rpy(double f,double t,double p){return Mul(Axis(2,p),Mul(Axis(1,t),Axis(0,f)));}
 static double[] Qrpy(double f,double t,double p){double cf=Math.Cos(f/2),sf=Math.Sin(f/2),ct=Math.Cos(t/2),st=Math.Sin(t/2),cp=Math.Cos(p/2),sp=Math.Sin(p/2);return new[]{cf*ct*cp+sf*st*sp,sf*ct*cp-cf*st*sp,cf*st*cp+sf*ct*sp,cf*ct*sp-sf*st*cp};}
 static double[,] Expanded(double f,double t,double p){double cf=Math.Cos(f),sf=Math.Sin(f),ct=Math.Cos(t),st=Math.Sin(t),cp=Math.Cos(p),sp=Math.Sin(p);return new double[,]{{cp*ct,cp*st*sf-sp*cf,cp*st*cf+sp*sf},{sp*ct,sp*st*sf+cp*cf,sp*st*cf-cp*sf},{-st,ct*sf,ct*cf}};}
 static double[,] Qmat(double[] q){double w=q[0],x=q[1],y=q[2],z=q[3];return new double[,]{{1-2*(y*y+z*z),2*(x*y-w*z),2*(x*z+w*y)},{2*(x*y+w*z),1-2*(x*x+z*z),2*(y*z-w*x)},{2*(x*z-w*y),2*(y*z+w*x),1-2*(x*x+y*y)}};}
 static double[] Normalize(double[] a){double n=0;foreach(double v in a)n+=v*v;n=Math.Sqrt(n);if(n==0)throw new Exception("zero quaternion");var b=new double[a.Length];for(int i=0;i<a.Length;i++)b[i]=a[i]/n;return b;}
 static double[] Matq(double[,] r){double[] a={(1+r[0,0]+r[1,1]+r[2,2])/4,(1+r[0,0]-r[1,1]-r[2,2])/4,(1-r[0,0]+r[1,1]-r[2,2])/4,(1-r[0,0]-r[1,1]+r[2,2])/4};int k=0;for(int i=1;i<4;i++)if(a[i]>a[k])k=i;var q=new double[4];q[k]=Math.Sqrt(Math.Max(0,a[k]));double d=4*q[k];if(k==0){q[1]=(r[2,1]-r[1,2])/d;q[2]=(r[0,2]-r[2,0])/d;q[3]=(r[1,0]-r[0,1])/d;}if(k==1){q[0]=(r[2,1]-r[1,2])/d;q[2]=(r[0,1]+r[1,0])/d;q[3]=(r[0,2]+r[2,0])/d;}if(k==2){q[0]=(r[0,2]-r[2,0])/d;q[1]=(r[0,1]+r[1,0])/d;q[3]=(r[1,2]+r[2,1])/d;}if(k==3){q[0]=(r[1,0]-r[0,1])/d;q[1]=(r[0,2]+r[2,0])/d;q[2]=(r[1,2]+r[2,1])/d;}return Normalize(q);}
 static double[] Euler(double[,] r){double ct=Math.Sqrt(r[0,0]*r[0,0]+r[1,0]*r[1,0]);double t=Math.Atan2(-r[2,0],ct);if(ct<1e-10)return new[]{0.0,t,Math.Atan2(-r[0,1],r[1,1])};return new[]{Math.Atan2(r[2,1],r[2,2]),t,Math.Atan2(r[1,0],r[0,0])};}
 static double[] Qmul(double[] a,double[] b){double w=a[0],x=a[1],y=a[2],z=a[3],v=b[0],i=b[1],j=b[2],k=b[3];return new[]{w*v-x*i-y*j-z*k,w*i+x*v+y*k-z*j,w*j-x*k+y*v+z*i,w*k+x*j-y*i+z*v};}
 static double[] Conj(double[] q){return new[]{q[0],-q[1],-q[2],-q[3]};}
 static double[] Rotate(double[] q,double[] p){var result=Qmul(Qmul(q,new[]{0.0,p[0],p[1],p[2]}),Conj(q));Near(new[]{result[0]},new[]{0.0},"sandwich scalar");return new[]{result[1],result[2],result[3]};}
 static double[] Slerp(double[] a,double[] b,double u){b=(double[])b.Clone();double dot=0;for(int i=0;i<4;i++)dot+=a[i]*b[i];if(dot<0){b=Neg(b);dot=-dot;}dot=Math.Max(-1,Math.Min(1,dot));var q=new double[4];if(dot>.9995){for(int i=0;i<4;i++)q[i]=(1-u)*a[i]+u*b[i];return Normalize(q);}double o=Math.Acos(dot);for(int i=0;i<4;i++)q[i]=Math.Sin((1-u)*o)/Math.Sin(o)*a[i]+Math.Sin(u*o)/Math.Sin(o)*b[i];return Normalize(q);}
 static void CheckRotation(double[,] r,double[] q,string name){Near(Mul(Trans(r),r),I(),name+" orthogonal");Near(new[]{Det(r)},new[]{1.0},name+" determinant");double n=0;foreach(double v in q)n+=v*v;Near(new[]{n},new[]{1.0},name+" norm");Near(r,Qmat(q),name+" independent representations");Near(r,Qmat(Neg(q)),name+" equivalent sign");Near(r,Qmat(Matq(r)),name+" stable matrix conversion");var e=Euler(r);Near(r,Rpy(e[0],e[1],e[2]),name+" Euler recovery");Near(Apply(r,new[]{.2,-.8,1.3}),Rotate(q,new[]{.2,-.8,1.3}),name+" sandwich");Near(Qmul(q,Conj(q)),new[]{1.0,0,0,0},name+" quaternion inverse");}
 public static object Run(){Checks=0;WorstError=0;CheckRotation(I(),new[]{1.0,0,0,0},"identity");for(int axis=0;axis<3;axis++)foreach(double angle in new[]{-Math.PI/2,Math.PI/2,Math.PI-1e-10,Math.PI}){var q=new[]{Math.Cos(angle/2),0.0,0.0,0.0};q[axis+1]=Math.Sin(angle/2);CheckRotation(Axis(axis,angle),q,"axis "+axis+" angle "+angle);}
 double f=Math.PI/6,t=-Math.PI/9,p=Math.PI/4;var mixed=Rpy(f,t,p);var mixedq=Qrpy(f,t,p);CheckRotation(mixed,mixedq,"mixed axes");foreach(double pitch in new[]{Math.PI/2,-Math.PI/2,Math.PI/2-1e-7,-Math.PI/2+1e-7})CheckRotation(Rpy(f,pitch,p),Qrpy(f,pitch,p),"singular pitch "+pitch);
 var k=Normalize(new[]{1.0,2.0,3.0});double angle180=Math.PI-1e-10;var nearq=new[]{Math.Cos(angle180/2),k[0]*Math.Sin(angle180/2),k[1]*Math.Sin(angle180/2),k[2]*Math.Sin(angle180/2)};CheckRotation(Qmat(nearq),nearq,"near180 mixed axis");
 var r=Axis(2,Math.PI/2);var camera=new[]{.2,0,1};var translation=new[]{0.0,0,.5};var result=Add(Apply(r,camera),translation);Near(result,new[]{0.0,.2,1.5},"demo forward");Near(Apply(Trans(r),Add(result,Neg(translation))),camera,"demo inverse");Near(Add(Apply(Mul(I(),r),camera),Add(Apply(I(),new[]{0.0,0,0}),translation)),result,"demo composed vs direct");
 var inner=Rpy(-.3,.4,.2);var outer=mixed;var ti=new[]{.3,-.2,.8};var to=new[]{.4,-.2,.7};var point=new[]{1.0,2,3};var composed=Add(Apply(Mul(outer,inner),point),Add(Apply(outer,ti),to));Near(composed,Add(Apply(outer,Add(Apply(inner,point),ti)),to),"general compose translated origins");var mixedresult=Add(Apply(mixed,point),to);Near(Apply(Trans(mixed),Add(mixedresult,Neg(to))),point,"mixed inverse");Near(Qmat(Qmul(mixedq,Qrpy(-.3,.4,.2))),Mul(mixed,inner),"quaternion composition");Near(Qmat(Qmul(Qmul(mixedq,Qrpy(-.3,.4,.2)),Conj(Qrpy(-.3,.4,.2)))),mixed,"relative quaternion");
 Near(Apply(Mul(Axis(2,Math.PI/2),Axis(0,Math.PI/2)),new[]{1.0,0,0}),new[]{0.0,1,0},"x then z");Near(Apply(Mul(Axis(0,Math.PI/2),Axis(2,Math.PI/2)),new[]{1.0,0,0}),new[]{0.0,0,1},"z then x");
 var q0=new[]{1.0,0,0,0};var q1=Qrpy(0,0,Math.PI/2);Near(Qmat(Slerp(q0,q1,0)),I(),"SLERP start");Near(Qmat(Slerp(q0,q1,1)),Qmat(q1),"SLERP end");Near(Qmat(Slerp(q0,q1,.5)),Axis(2,Math.PI/4),"SLERP midpoint");Near(Qmat(Slerp(q0,Neg(q1),.5)),Axis(2,Math.PI/4),"SLERP negative sign");Near(Qmat(Slerp(q1,Neg(q1),.5)),Qmat(q1),"SLERP antipodal equivalence");Near(Qmat(Slerp(q0,Qrpy(0,0,1e-8),.5)),Axis(2,5e-9),"SLERP near identity");
 
 Near(mixed,Expanded(f,t,p),"expanded Euler formula");
 Near(mixedresult,new[]{.030202437453,-.241628163324,4.423105808160},"printed mixed example",2e-9);
 return new {checks=Checks,worstError=WorstError,mixedQuaternion=mixedq,mixedPoint=mixedresult,demoPoint=result,status="PASS"};}
}
